function fixAlternative(q: [string, number, string, string[], number, string]): { options: string[]; correct: number; explanation: string } {
  const product = q[0];
  const allowed = ALT_MAP[product];
  if (!allowed || allowed.length === 0) return { options: q[3], correct: q[4], explanation: q[5] };
  const me = SHOP_PRODUCTS.find(p => p.name === product);
  const used = new Set<string>([product]);
  const options = [...q[3]];
  let correct = q[4];
  if (!allowed.includes(options[correct])) options[correct] = allowed[0];
  options.forEach(o => used.add(o));
  // Falsche Antworten dürfen nicht in der Liste stehen – sonst wären sie ja auch richtig
  const pool = SHOP_PRODUCTS.filter(p => p.name !== product && !allowed.includes(p.name) && (me ? p.group === me.group : true) && (!me || !me.breadType || p.breadType !== me.breadType));
  const fallback = SHOP_PRODUCTS.filter(p => p.name !== product && !allowed.includes(p.name) && (me ? p.group === me.group : true));
  options.forEach((o, i) => {
    if (i === correct || !allowed.includes(o)) return;
    const sub = [...pool, ...fallback].find(p => !used.has(p.name));
    if (sub) { options[i] = sub.name; used.add(sub.name); }
  });
  const explanation = allowed.length === 1
    ? `Für „${product}“ empfehlen wir „${allowed[0]}“.`
    : `Für „${product}“ passen: ${allowed.map(a => `„${a}“`).join(', ')}. Hier im Quiz war „${options[correct]}“ dabei.`;
  return { options, correct, explanation };
}

/** Für Korrekturen des Ausbilders: eine „Ausverkauft“-Frage neu an die (geänderte) Alternativen-Liste anpassen */
export function refixAlternativeQuestion(q: Question): Question {
  if (!q.product) return q;
  const fx = fixAlternative([q.product, 0, q.question, q.options, q.correct, q.explanation]);
  return { ...q, options: fx.options, correct: fx.correct, explanation: fx.explanation };
}

const EXTRA_QUESTIONS: Question[] = [
  ...ALTERNATIVEN.map((q, i): Question => {
    const fx = fixAlternative(q);
    return {
      id: 4001 + i, category: 'Service & Verkauf', level: q[1] === 1 ? 'hard' : 'easy',
      question: q[2], options: fx.options, correct: fx.correct, explanation: fx.explanation, product: q[0]
    };
  }),
  ...BACKTAGE.map((q, i): Question => ({
    id: 4501 + i, category: 'Sortiment & Warenkunde', level: q[1] === 1 ? 'hard' : 'easy',
    question: q[2], options: q[3], correct: q[4], explanation: q[5], product: q[0], subgroup: BACKTAGE_SUBGROUPS[q[0]]
  }))
];

// Fragen rund um Soja werden überall ausgeblendet (IDs der übrigen Fragen bleiben gleich)
const ohneSoja = (q: Question) => !/soja/i.test([q.question, q.explanation, ...q.options].join(' '))
  // Der Wunderzopf wird nicht geschnitten, deshalb keine Schnittstärke-Frage dazu
  && !(q.product === 'Wunderzopf' && /Schnittstärke/.test(q.question));
// Die App duzt: Fragen an die Mitarbeiter in Du-Form (Sätze zum Kunden bleiben beim Sie)
const DU_FORM: [string, string][] = [["melden Sie sich so früh wie möglich telefonisch oder per WhatsApp bei Frau Azhari und in Ihrer Filiale", "meldest du dich so früh wie möglich telefonisch oder per WhatsApp bei Frau Azhari und in deiner Filiale"], ["Wann dürfen Sie auf keinen Fall", "Wann darfst du auf keinen Fall"], ["Wie verhalten Sie sich", "Wie verhältst du dich"], ["Bei wem reichen Sie Ihren Urlaubsantrag", "Bei wem reichst du deinen Urlaubsantrag"], ["Woher bekommen Sie das Formular", "Woher bekommst du das Formular"], ["Das Urlaubsformular erhalten Sie nach den Betriebsferien oder auf Nachfrage bei Ihrer Filialleitung", "Das Urlaubsformular erhältst du nach den Betriebsferien oder auf Nachfrage bei deiner Filialleitung"], ["Wann werden Ihnen die Kosten", "Wann werden dir die Kosten"], ["Nur wenn Sie die Belehrung innerhalb der Probezeit absolvieren und bescheinigen lassen", "Nur wenn du die Belehrung innerhalb der Probezeit absolvierst und bescheinigen lässt"], ["Nur wenn Sie die Quittung im Betrieb mitbringen und vorlegen", "Nur wenn du die Quittung im Betrieb mitbringst und vorlegst"], ["Nur wenn Sie die Erstattung innerhalb von vier Wochen schriftlich beantragen", "Nur wenn du die Erstattung innerhalb von vier Wochen schriftlich beantragst"], ["wenn Sie die Quittung mitbringen", "wenn du die Quittung mitbringst"], ["An wen wenden Sie sich, wenn Sie unsicher sind", "An wen wendest du dich, wenn du unsicher bist"], ["Vorab an Ihre Filialleitung", "Vorab an deine Filialleitung"], ["Sollten Sie sich unsicher sein, was erlaubt ist, sprechen Sie bitte vorab Ihre Filialleitung an", "Wenn du dir unsicher bist, was erlaubt ist, sprich bitte vorab deine Filialleitung an"], ["Was machen Sie mit einem Gebäckstück, das Ihnen versehentlich", "Was machst du mit einem Gebäckstück, das dir versehentlich"], ["Was müssen Sie tun, wenn Sie bereits vor Ihrem Start bei Hinkel ein gültiges Gesundheitszeugnis besitzen", "Was musst du tun, wenn du bereits vor deinem Start bei Hinkel ein gültiges Gesundheitszeugnis besitzt"], ["Sie müssen es beim Gesundheitsamt", "Du musst es beim Gesundheitsamt"], ["Es reicht aus, wenn Sie dieses gültige Zeugnis im Betrieb vorlegen", "Es reicht aus, wenn du dieses gültige Zeugnis im Betrieb vorlegst"], ["Sie müssen es nach einem Jahr", "Du musst es nach einem Jahr"], ["Sie müssen zusätzlich bei der Betriebsärztin", "Du musst zusätzlich bei der Betriebsärztin"], ["Sofern Sie bereits im Besitz eines gültigen Gesundheitszeugnisses sind", "Wenn du bereits ein gültiges Gesundheitszeugnis hast"], ["Wie heben Sie schwere", "Wie hebst du schwere"], ["Woran erkennen Sie", "Woran erkennst du"], ["Warum sollten Sie Kunden", "Warum solltest du Kunden"], ["Empfehlen Sie Kunden,", "Empfiehl Kunden,"], ["Wie erklären Sie", "Wie erklärst du"], ["Welche Brote empfehlen Sie", "Welche Brote empfiehlst du"], ["Was empfehlen Sie laut Tabelle", "Was empfiehlst du laut Tabelle"], ["Was sagen Sie richtig", "Was sagst du richtig"], ["stellen Sie die Maschine ein", "stellst du die Maschine ein"], ["Welche Schnittstärke wählen Sie", "Welche Schnittstärke wählst du"], ["Welches Brot empfehlen Sie ihm", "Welches Brot empfiehlst du ihm"], ["Was empfehlen Sie?", "Was empfiehlst du?"], ["Was bieten Sie an?", "Was bietest du an?"], ["Was teilen Sie ihm", "Was teilst du ihm"], ["Wie gehen Sie bei", "Wie gehst du bei"], ["Wie prüfen Sie an der Kasse", "Wie prüfst du an der Kasse"], ["Wie wandeln Sie im", "Wie wandelst du im"], ["Wie reagieren Sie professionell", "Wie reagierst du professionell"]];
const duzen = (t: string) => (typeof t === 'string' ? DU_FORM.reduce((acc, [a, b]) => acc.split(a).join(b), t) : t);
// Einheitliche Anführungszeichen: 'Wort' wird zu „Wort“
const fixQuotes = (t: string) => (typeof t === 'string' ? duzen(t).replace(/(^|[\s(\/„-])'([^'\n]{1,140}?)'(?=[\s.,:;?!)\/-]|$)/g, '$1„$2“') : t);
const tidyQuestion = <T extends Question>(q: T): T => {
  q.question = fixQuotes(q.question);
  q.options = q.options.map(fixQuotes);
  if (q.explanation) q.explanation = fixQuotes(q.explanation);
  return q;
};
// „Welche Beschreibung passt?“: Texte neutral machen, damit „Unser …“ / „Unsere …“ nichts verrät
// und nur der Produktname ausgeblendet wird (nicht Teile davon wie „Butter“ bei Butter-Croissant)
const reEsc = (t: string) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const PLURAL_VERB = /^(sind|werden|haben|bestehen|verbinden|gehören|vereinen|bringen|schmecken|überzeugen|kommen|stehen|bekommen|tragen|erhalten|enthalten)\b/;
export function neutralDescription(masked: string): string {
  const re = new RegExp('^' + reEsc(masked).replace(/…/g, '(.{1,60}?)'));
  const loose = new RegExp(reEsc(masked).replace(/…/g, '(.{1,60}?)'));
  let src: (typeof SHOP_PRODUCTS)[number] | undefined = SHOP_PRODUCTS.find(p => re.test(p.description)) || SHOP_PRODUCTS.find(p => loose.test(p.description));
  let t = masked;
  let m = src ? (re.exec(src.description) || loose.exec(src.description)) : null;
  if (!src) {
    // Text wurde im Shop leicht geändert: Produkt mit den meisten gleichen Wörtern suchen
    const words = masked.replace(/…/g, ' ').toLowerCase().split(/[^a-zäöüß]+/).filter(w => w.length > 3);
    let best = 0;
    for (const p of SHOP_PRODUCTS) {
      const d = p.description.toLowerCase();
      const hit = words.filter(w => d.includes(w)).length / Math.max(1, words.length);
      if (hit > best) { best = hit; src = p; }
    }
    if (best < 0.75) src = undefined;
    if (src) {
      const n = (masked.match(/[.!?](\s|$)/g) || ['.']).length;
      const parts = src.description.match(/[^.!?]+[.!?]+/g) || [src.description];
      t = parts.slice(0, n).join('').trim();
    }
  }
  if (src) {
    if (m) t = m[0];
    const names = [src.name, ...(src.aliases || [])].filter(Boolean).sort((a, b) => b.length - a.length);
    names.forEach(n => { t = t.replace(new RegExp(reEsc(n) + '(-[A-Za-zÄÖÜäöüß]+|en|n|s)?', 'gi'), '…'); });
  }
  // Satzanfang „Unser(e) … ist/sind“ neutral formulieren (auch wenn dort ein anderer Produktname steht)
  const lead = /^(Unser|Unsere|Unseren|Unserem)\s+((?:…[^\s,]*|[A-ZÄÖÜa-zäöüß][\wäöüßÄÖÜ-]*)\s+){1,4}?(?=(ist|sind|wird|werden|hat|haben|besteht|bestehen|verbindet|verbinden|gehört|gehören|vereint|vereinen|bringt|schmeckt|kommt|steht|trägt|enthält|überzeugt)\b)/.exec(t);
  if (lead) {
    const rest = t.slice(lead[0].length);
    t = (PLURAL_VERB.test(rest) ? 'Dieses Produkt ' + rest.replace(PLURAL_VERB, (v) => ({ sind: 'ist', werden: 'wird', haben: 'hat', bestehen: 'besteht', verbinden: 'verbindet', gehören: 'gehört', vereinen: 'vereint', bringen: 'bringt', schmecken: 'schmeckt', überzeugen: 'überzeugt', kommen: 'kommt', stehen: 'steht', bekommen: 'bekommt', tragen: 'trägt', erhalten: 'erhält', enthalten: 'enthält' } as Record<string, string>)[v] || v) : 'Dieses Produkt ' + rest);
  } else if (/^Unser(e)?\s+…/.test(t)) {
    t = t.replace(/^Unser(e)?\s+…\S*/, 'Dieses Produkt');
  }
  return t.replace(/…\s+…/g, '…').replace(/Hinkel-…/g, 'Hinkel-Gebäck');
}
const tidyBeschreibung = (q: Question): Question => {
  if (!/^Welche Beschreibung passt zu „/.test(q.question)) return q;
  const opts = q.options.map(neutralDescription);
  if (new Set(opts).size !== opts.length) return q; // Sicherheit: keine doppelten Antworten
  q.options = opts;
  return q;
};
// Doppelte Antworten (gleicher Inhalt, nur andere Reihenfolge) durch eine andere falsche Antwort ersetzen
const sameAnswer = (t: string) => t.split(/,\s*(?![^()]*\))/).map(x => x.trim().toLowerCase()).sort().join('|');
const fixDuplicateOptions = (list: Question[]): Question[] => {
  const typeOf = (q: Question) => q.question.replace(/„[^“]*“/g, '…');
  const pool: Record<string, string[]> = {};
  list.forEach(q => { (pool[typeOf(q)] = pool[typeOf(q)] || []).push(...q.options); });
  return list.map(q => {
    const keys = q.options.map(sameAnswer);
    if (new Set(keys).size === keys.length) return q;
    const opts = [...q.options];
    const seen = new Set<string>([sameAnswer(opts[q.correct])]);
    const cand = (pool[typeOf(q)] || []).filter(o => o.length > 0);
    let k = (Number(q.id) * 7) % Math.max(1, cand.length);
    opts.forEach((o, i) => {
      if (i === q.correct) return;
      const key = sameAnswer(o);
      if (!seen.has(key)) { seen.add(key); return; }
      for (let tries = 0; tries < cand.length; tries++) {
        const c = cand[(k + tries) % cand.length];
        if (!seen.has(sameAnswer(c)) && !keys.includes(sameAnswer(c))) { opts[i] = c; seen.add(sameAnswer(c)); k += tries + 1; break; }
      }
    });
    return { ...q, options: opts };
  });
};
export const questions: Question[] = fixDuplicateOptions([...rawQuestions, ...SORTIMENT_QUESTIONS, ...EXTRA_QUESTIONS].filter(ohneSoja).map(tidyQuestion).map(tidyBeschreibung));

export const examQuestions: Question[] = compactExams
  .filter((e): e is [number, 'ZP' | 'AP', number, string, string, string[], number, string] => Array.isArray(e) && e.length > 0 && e[0] !== undefined)
  .map(e => ({
    id: e[0],
    category: "Prüfung",
    level: e[1] === 'ZP' ? 'easy' : 'hard',
    examGroup: e[1],
    examNumber: e[2],
    examTitle: e[3],
    question: e[4],
    options: e[5],
    correct: e[6],
    explanation: e[7]
  })).map(q => tidyQuestion(q as Question));